                pos_diag.add(row + col)
                neg_diag.add(row - col)
                board[row][col] = "Q"

                backtrack(row + 1)

                board[row][col] = "."
                cols.discard(col)
                pos_diag.discard(row + col)
                neg_diag.discard(row - col)

